#include "SafetyControl.hpp"
#include <cassert>
#include <iostream>
int main(){using S=SafetyControl; S s; assert(s.update(0,1,1,1)==S::RESERVE); for(unsigned i=0;i<6;i++) assert(s.sample(i*10000,23,1,i,true)); assert(s.update(50000,1,1,1)==S::RECOVERY); assert(s.update(50001,1,1,1,true)==S::NORMAL); assert(!s.sample(60000,23,1,5,true)); assert(!s.sample(60000,NAN,1,6,true)); assert(!s.sample(60000,23,1,6,false)); assert(s.update(169999,1,1,1)==S::NORMAL); assert(s.update(170000,1,1,1)==S::RESERVE); assert(s.update(170001,0,1,0)==S::OFF); assert(s.update(170001,1,1,0)==S::OT_FAULT); assert(s.update(170001,1,0,1)==S::MANUAL); for(unsigned i=0;i<6;i++) assert(s.sample(180000+i*10000,23,2,i,true)); assert(s.update(230000,1,1,1)==S::RECOVERY); assert(s.update(230001,1,1,0)==S::OT_FAULT); assert(s.update(230002,1,1,1,true)==S::RECOVERY); assert(!s.sample(240000,23,1,999,true)); assert(s.sample(240000,23,3,0,true)); assert(s.update(240000,1,1,1)==S::RESERVE); S w; assert(w.sample(UINT32_MAX-5000,22,1,1,true)); assert(w.sample(4999,22,1,2,true)); assert(w.update(124999,1,1,1)==S::RESERVE); std::cout<<"PASS: assertions, startup, recovery, stale, duplicate, invalid, manual off, OT fault, timer wrap\n";}
